{
  "components": [
    {
      "type": "claim",
      "quote": "For the purpose of inspecting the potential planning zones, the SFOE may arrange for an on-site visit by the support group.",
      "gist": "SFOE can arrange on-site visits by support group to inspect potential planning zones."
    },
    {
      "type": "claim",
      "quote": "The latter then examines the application documents and recommends a planning zone, which has to be large enough to ensure that more than one planning corridor can be developed.",
      "gist": "Support group reviews documents and recommends a sufficiently large planning zone for multiple corridors."
    },
    {
      "type": "claim",
      "quote": "Based on the recommendation by the support group, the SFOE prepares a draft version of the detailed plan and initiates the consultation and participation procedure in the cantons.",
      "gist": "SFOE drafts detailed plan and starts consultation in cantons using support group's recommendation."
    },
    {
      "type": "obligation",
      "quote": "Interested persons, organisations and associations have the opportunity to submit comments and statements of position within the scope of the consultation and participation procedure.",
      "gist": "Interested parties must be allowed to submit comments during consultation."
    }
  ]
}
